"""Authored fictional consultations; no model-generated or empirical results."""
import json
from pathlib import Path
scenarios=[
 dict(id='clinical-ai',title='Who should have the final say when AI triages patients?',question='Where should an AI triage system assist clinicians, and where must people retain control?',claims=['AI may prioritise routine referrals only when a clinician can override its recommendation.','Patients must be told when AI materially influences the priority of their referral.','An independent subgroup performance audit must be completed before deployment.','Emergency referrals must never be downgraded solely on an AI recommendation.'],arguments=[('An override preserves clinical responsibility while allowing useful assistance.','An override is insufficient if workload makes review nominal.'),('Disclosure gives patients a route to question an unexpected delay.','A generic disclosure can confuse patients without explaining the actual decision.'),('An aggregate score can conceal unequal performance across patient groups.','A mandatory audit can delay useful tools where subgroup samples are small.'),('Urgent clinical concern should not be overruled by an automated score.','Absolute rules could retain avoidable false alarms when evidence is strong.')],people=[('Emergency physician','Safety depends on escalation working during a busy shift.'),('Patient advocate','Patients need an understandable explanation and a real appeal route.'),('Rural general practitioner','Small services need workable safeguards with limited staff.'),('Clinical AI researcher','Validation should distinguish model errors from workflow failures.'),('Nursing lead','A nominal human override is not enough without time and authority.'),('Hospital operations lead','Queue delays also harm patients and must be monitored.')],r2=[[4,4,5,5],[3,5,5,5],[4,3,3,5],[5,4,5,4],[2,5,4,5],[4,3,2,4]],r3=[[4,5,5,5],[4,5,5,5],[4,4,3,5],[4,4,5,5],[2,5,5,5],[4,4,3,4]],feedback='The nursing lead distinguished a usable override from a nominal one; the rural practitioner raised limited audit samples. Participants retained disagreement about the audit threshold rather than treating disclosure as consent.'),
 dict(id='assessment-ai',title='Should universities replace essays in the age of AI?',question='How should universities assess learning when students can use generative AI?',claims=['Students may use generative AI in assessed coursework if its role is disclosed.','Every degree must include an assessment where students explain their own reasoning orally.','AI-detector scores alone must never establish academic misconduct.','All take-home essays should be replaced with supervised examinations.'],arguments=[('Disclosure makes permitted assistance inspectable.','Disclosure does not establish which reasoning belongs to the student.'),('An oral explanation can reveal whether a student understands their work.','Oral assessment can disadvantage anxious or disabled students unless alternatives exist.'),('A detector score is not direct evidence of who authored a passage.','Institutions still need a practical way to investigate suspicious submissions.'),('Supervision constrains undisclosed assistance.','Replacing every essay removes valuable research and revision skills.')],people=[('Undergraduate representative','Assessment should reward learning rather than access to expensive tools.'),('Disability adviser','Students need accessible ways to demonstrate understanding.'),('Humanities lecturer','Extended writing develops reasoning through revision.'),('Computer science lecturer','Students must learn to critique tools they will encounter at work.'),('Academic integrity officer','Misconduct decisions need reviewable evidence and a fair process.'),('Assessment director','Any new assessment format must work at large cohort sizes.')],r2=[[5,4,5,1],[4,2,5,1],[2,4,5,2],[5,5,4,2],[3,4,4,3],[4,3,5,4]],r3=[[5,4,5,1],[4,2,5,1],[3,4,5,1],[5,4,5,1],[4,4,5,2],[4,3,5,2]],feedback='The disability adviser identified accessibility limits to a universal oral requirement. The humanities lecturer explained what would be lost by replacing all essays. The panel increasingly opposed the blanket replacement while preserving disagreement about oral assessment.'),
 dict(id='coastal-futures',title='Protect the coastline—or help communities move?',question='How should a coastal town balance flood protection, voluntary relocation and fairness?',claims=['Residents in repeatedly flooded homes should be offered voluntary relocation grants.','Publicly funded coastal defences should be prioritised using property values alone.','Any relocation programme must include support for renters as well as owners.','New housing should be prohibited in the highest-risk flood zone.'],arguments=[('A voluntary option lets households plan before repeated emergencies.','A nominal choice is not voluntary when services are withdrawn first.'),('Property values provide a transparent estimate of assets protected.','Property values alone privilege wealthy places and miss community losses.'),('Renters also lose homes, social networks and access to services.','A renter support programme needs clear eligibility to avoid excluding informal tenants.'),('Avoiding new exposure can reduce future displacement.','A blanket prohibition may worsen shortages where few alternative sites exist.')],people=[('Long-term resident','Relocation can break relationships built over decades.'),('Tenant organiser','Compensation must not stop at the legal owner of a building.'),('Coastal engineer','Defences have maintenance limits and cannot remove every risk.'),('Local business owner','Schools, jobs and customers must remain viable during transition.'),('Council housing officer','Affordable alternatives are needed before restricting new supply.'),('Public finance analyst','The town should make distributional trade-offs explicit.')],r2=[[2,1,4,3],[4,1,5,4],[5,2,4,5],[3,3,3,2],[4,2,5,2],[5,3,4,4]],r3=[[3,1,5,3],[4,1,5,4],[5,1,5,5],[3,2,4,2],[4,1,5,2],[5,2,5,4]],feedback='The tenant organiser exposed the gap between property compensation and displacement costs. Participants rejected property value as the sole criterion more strongly, but housing-supply concerns sustained disagreement about a building prohibition.'),
 dict(id='school-phones',title='A phone-free school day—with whose exceptions?',question='What smartphone policy balances attention, safety, accessibility and student autonomy?',claims=['Personal smartphones should be stored away during lessons.','Students must retain access to a phone when required by an agreed medical or accessibility plan.','Schools should prohibit personal smartphone use during every break and lunchtime.','Schools should use routine searches of students’ phones to enforce the policy.'],arguments=[('Putting phones away can create a predictable classroom boundary.','Storage rules need a safe and practical retrieval process.'),('An agreed adjustment makes the rule compatible with individual needs.','Exceptions require care so pupils are not forced to disclose private information publicly.'),('A full-day rule is simpler to administer consistently.','Breaks are different from lessons and allow students to practise autonomy.'),('Searches might identify breaches that ordinary supervision misses.','Routine access to private messages is disproportionate to a classroom rule.')],people=[('Student representative','Students should have a voice in rules that govern their daily lives.'),('Classroom teacher','Consistent rules reduce repeated negotiation during lessons.'),('Parent representative','Families need a reliable way to contact children in exceptional circumstances.'),('School nurse','Medical access must be dependable without publicly identifying a condition.'),('Safeguarding lead','Intervention should be proportionate and protect private information.'),('Headteacher','A policy needs to be workable without creating a disciplinary spiral.')],r2=[[4,5,1,1],[5,4,5,2],[4,5,3,2],[4,5,2,1],[5,5,4,3],[5,4,5,3]],r3=[[4,5,1,1],[5,5,4,1],[4,5,2,1],[4,5,2,1],[5,5,3,2],[5,5,4,2]],feedback='The nurse clarified that exceptions are adjustments rather than privileges. The student representative separated lesson boundaries from break-time autonomy. Routine searches lost support, while the full-day rule remained contested.')
]
labels={1:'Strongly disagree',2:'Disagree',3:'Neither agree nor disagree',4:'Agree',5:'Strongly agree'}
conf=['Not at all confident','Slightly confident','Moderately confident','Very confident','Extremely confident']
for s in scenarios:
 people=[]
 for i,(role,concern) in enumerate(s.pop('people')):
  p={'id':f'{s["id"]}-p{i+1}','role':role,'opening':concern+' '+ ' '.join(s['arguments'][j][0 if v>=4 else 1] for j,v in enumerate(s['r2'][i]))}
  for rn in [2,3]:
   votes=s[f'r{rn}'][i];reasons=[]
   for j,v in enumerate(votes):
    reason=s['arguments'][j][0 if v>=4 else 1]
    if v==3:reason='I see a case for both sides. '+reason
    if rn==3:
     reason=('I changed my rating after reviewing the panel’s reasons. ' if v!=s['r2'][i][j] else 'I retain my rating after reviewing the panel’s reasons. ')+reason
    reasons.append(reason+' '+concern)
   p[f'round{rn}']={'votes':[labels[v] for v in votes],'confidence':[conf[min(4,2+(abs(v-3)>0)+(rn==3 and j%2==0))] for j,v in enumerate(votes)],'reasons':reasons}
  people.append(p)
 s['people']=people
 for k in ['r2','r3','arguments']:s.pop(k)
Path('scripts/fixtures/new-dev-surveys.json').write_text(json.dumps({'provenance':'Assistant-authored fictional simulations. Positions, confidence and changes are scripted; no real experts or model evaluation. No OpenRouter calls.','scenarios':scenarios},indent=2)+'\n')
